using System.Collections.Generic;
using CardCleaner.Scripts.Core.Interfaces;
using Godot;

namespace CardCleaner.Scripts.Features.Deckbuilder.Services;

/// <summary>
/// Simple map data structure using tile IDs
/// </summary>
public class SimpleMapData : IGridMap
{
    private HashSet<Vector2I>? _passableTilesSet;

    public string[,] TileIds { get; set; } = new string[0, 0];

    /// <summary>
    /// Background terrain generated by WFC phase 1 for dual-grid rendering.
    /// </summary>
    public string[,]? BackgroundLayer { get; set; }

    /// <summary>
    /// Foreground auto-tile terrain generated by WFC phase 2 for dual-grid rendering.
    /// </summary>
    public string[,]? ForegroundLayer { get; set; }

    public string[,]? BiomeMap { get; set; }
    public Vector2I Size { get; set; }
    public Vector2I PlayerStart { get; set; }
    public List<Vector2I> EnemyPositions { get; set; } = new();
    public List<Vector2I> PassableTiles { get; set; } = new();

    /// <summary>
    /// Pre-selected variation indices for tiles using VariationMode.PerGeneration.
    /// </summary>
    public Dictionary<string, int> PerGenerationVariants { get; set; } = new();

    /// <summary>
    /// Pre-selected tile IDs for variation groups using PerGeneration mode.
    /// </summary>
    public Dictionary<string, string> PerGenerationGroupVariants { get; set; } = new();

    /// <summary>
    /// Context-selected variation indices for tiles using VariationMode.Contextual.
    /// </summary>
    public Dictionary<Vector2I, int> ContextualVariants { get; set; } = new();

    // ASSUMPTION (#241): readers get read-only views of the settable collections; the generator keeps writing.
    IReadOnlyList<Vector2I> IGridMap.EnemyPositions => EnemyPositions;

    public string GetBiomeAt(Vector2I pos)
    {
        if (BiomeMap == null || !IsInBounds(pos))
            return "plains";
        return BiomeMap[pos.Y, pos.X];
    }

    public bool IsPassable(Vector2I pos)
    {
        if (!IsInBounds(pos))
            return false;

        // ASSUMPTION (#288): PassableTiles is the only source now that the map holds no registry;
        // a map with no passable tiles reports no passable position.
        return PassableTiles.Count > 0 && PassableTilesSet.Contains(pos);
    }

    public bool IsTransparent(Vector2I pos)
    {
        if (!IsInBounds(pos))
            return false;

        // ASSUMPTION (#288): PassableTiles is the only source; most passable tiles are also transparent.
        return PassableTiles.Count > 0 && PassableTilesSet.Contains(pos);
    }

    private bool IsInBounds(Vector2I pos)
    {
        return pos.X >= 0 && pos.X < Size.X && pos.Y >= 0 && pos.Y < Size.Y;
    }

    private HashSet<Vector2I> PassableTilesSet => _passableTilesSet ??= new HashSet<Vector2I>(PassableTiles);

    /// <summary>
    /// Gets the tile ID at a position. Returns empty string for out-of-bounds positions.
    /// </summary>
    public string GetTileId(Vector2I pos)
    {
        if (!IsInBounds(pos))
            return string.Empty;
        return TileIds[pos.Y, pos.X];
    }

}
